INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (101, 'RED', 'New York');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (1001, 101, 2, '2022-01-01', 1000);

